import React, { useState, useRef } from 'react';

const VoiceInput = ({ onSendVoice }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [audioBlob, setAudioBlob] = useState(null);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);

  const handleStartRecording = async () => {
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorderRef.current = new MediaRecorder(stream);
        audioChunksRef.current = [];

        mediaRecorderRef.current.ondataavailable = (event) => {
          audioChunksRef.current.push(event.data);
        };

        mediaRecorderRef.current.onstop = () => {
          const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' }); // Or audio/wav, etc.
          setAudioBlob(blob);
          // For now, just log it. API call will happen in onSendVoice prop
          console.log('Recorded audio blob:', blob);
          if (onSendVoice) {
             onSendVoice({ type: 'voice', content: blob });
          } else {
             alert('Voice recorded (simulated). Check console.');
          }
          // Reset for next recording
          audioChunksRef.current = [];
          // Optionally stop tracks to release microphone
          stream.getTracks().forEach(track => track.stop());
        };

        mediaRecorderRef.current.start();
        setIsRecording(true);
        setAudioBlob(null); // Clear previous recording
      } catch (err) {
        console.error('Error accessing microphone:', err);
        alert('Error accessing microphone. Please check permissions.');
      }
    } else {
      alert('Audio recording is not supported in this browser.');
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const buttonStyle = {
    padding: '10px 15px',
    border: 'none',
    backgroundColor: isRecording ? '#dc3545' : 'var(--secondary-color)',
    color: 'white',
    borderRadius: 'var(--border-radius, 8px)',
    cursor: 'pointer',
    fontSize: '16px',
    minWidth: '120px'
  };

  return (
    <div>
      <button onClick={isRecording ? handleStopRecording : handleStartRecording} style={buttonStyle}>
        {isRecording ? 'Stop Recording' : 'Start Voice'}
      </button>
      {audioBlob && !isRecording && (
        <p style={{fontSize: '12px', marginTop: '5px'}}>Recording complete. Ready to send.</p>
      )}
    </div>
  );
};

export default VoiceInput;
